def to_p16_f16(raw: bytes):
    """`F16` -> P16: keep the fp16, widen only to decode.  fp16 -> fp32 is always exact."""
    return np.frombuffer(raw, dtype="<f2"), np.ones(len(raw) // 2, dtype=np.float32)


